css:
/* Image card grid: a photo over a pale blue panel with a centred title and text, three across. */
[data-bz-node="ic-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="image-card-grid"] .bz-block { padding-block: 0; }
[data-bz-section="image-card-grid"] [data-bz-node="ic-row"] { padding-inline: 20px; column-gap: 20px; row-gap: 36px; align-items: stretch; }
[data-bz-section="image-card-grid"] [data-bz-node^="ic-card"] { background: #ebf7ff; border: 1px solid #a5d3ee; box-sizing: border-box; display: flex; flex-direction: column; }
[data-bz-section="image-card-grid"] .bz-figure { margin: 0; }
[data-bz-section="image-card-grid"] .bz-figure img { display: block; width: 100%; height: auto; aspect-ratio: 3 / 2; object-fit: cover; border-radius: 0; }
[data-bz-section="image-card-grid"] h3 { margin: 0; padding: 32px 8px 0; text-align: center; font: 700 1.5rem / 1.2 var(--font-heading); color: var(--accent); letter-spacing: 0; }
[data-bz-section="image-card-grid"] .bz-text p { margin: 16px 0 0; padding: 0 34px 31px; text-align: center; font: 400 0.945rem / 1.5 var(--font-body); color: #000; max-width: none; }
@media (max-width: 1100px) { [data-bz-section="image-card-grid"] [data-bz-node="ic-row"] > .bz-col { grid-column: span 6; } }
@media (max-width: 640px) { [data-bz-section="image-card-grid"] [data-bz-node="ic-row"] { padding-inline: 0; } [data-bz-section="image-card-grid"] [data-bz-node="ic-row"] > .bz-col { grid-column: 1 / -1; } }
